import React, { useState } from 'react';
import { GoogleOAuthProvider } from '@react-oauth/google';
import { BrowserRouter, Routes, Route } from 'react-router-dom';
import LoginPage from './components/LoginPage';
import HomePage from './components/HomePage';
import Clipper from './components/clipper';
import SEO from './components/Seo';
import ClipPreview from './components/ClipPreview';
import api from './api'; // Assuming your api.js file is in the same directory.

const App = () => {
  // State to store the video URL, video ID, and video thumbnail
  const [videoUrl, setVideoUrl] = useState('');
  const [videoId, setVideoId] = useState('');
  const [videoThumbnail, setVideoThumbnail] = useState('');
  const [clips, setClips] = useState([]); // To store the generated clips
  const [loading, setLoading] = useState(false); // To manage loading state

  // Handle the "Generate Clips" button functionality
  const handleGenerateClips = async (url) => {
    setLoading(true); // Set loading to true to show "Generating..." message

    try {
      // Fetch video metadata (can include duration, title, thumbnail, etc.)
      const videoMetadata = await api.fetchVideoMetadata(url);
      setVideoId(videoMetadata.id);
      setVideoThumbnail(videoMetadata.thumbnail);
      setVideoUrl(videoMetadata.url);

      // Simulate backend logic for downloading and generating video clips
      const generatedClips = await api.downloadAndUploadVideo(url);
      setClips(generatedClips); // Store the clips data

      setLoading(false); // Hide loading spinner after clips are generated
    } catch (error) {
      console.error("Error generating clips:", error.message);
      setLoading(false); // Hide loading spinner in case of error
    }
  };

  return (
    <GoogleOAuthProvider clientId={process.env.REACT_APP_GOOGLE_CLIENT_ID}>
      <BrowserRouter>
        <Routes>
          <Route path="/" element={<LoginPage />} />
          <Route
            path="/home"
            element={<HomePage setVideoUrl={setVideoUrl} handleGenerateClips={handleGenerateClips} />}
          />
          <Route
            path="/clipper"
            element={
              <Clipper
                setVideoUrl={setVideoUrl}
                setVideoId={setVideoId}
                setVideoThumbnail={setVideoThumbnail}
                handleGenerateClips={handleGenerateClips}
                loading={loading}
              />
            }
          />
          <Route
            path="/seo"
            element={<SEO videoId={videoId} videoThumbnail={videoThumbnail} />}
          />
          <Route
            path="/clippreview"
            element={<ClipPreview videoUrl={videoUrl} clips={clips} />}
          />
          <Route path="*" element={<h2>Page Not Found</h2>} />
        </Routes>
      </BrowserRouter>
    </GoogleOAuthProvider>
  );
};

export default App;
